    if (!incoming) {
      setTimeout(poll, 2000);
      return;
    }
    root.dataset.live = incoming.dataset.live ?? "";
    root.dataset.since = incoming.dataset.since ?? "";
    root.innerHTML = incoming.innerHTML;
